        a=line.rstrip('\n').split('\t'); d.setdefault(a[0],[]).append((int(a[1]),int(a[2]),int(a[3])))
    return d
def model2(s,h=1.0,minl=1,X=10.0):
    out=[]; sc=0.0; mx=0.0; mi=-1; start=-1; hits=0; sh=0; mh=0
    for i,c in enumerate(s):
        hit = c in 'GCS'
        if hit:
            if sc<=0: start=i; sh=hits
            hits+=1; sc+=h
        else:
            sc-=1.0
            if sc<0: sc=0.0
