import sys
def load(fn):
    d={}
    for line in open(fn):
        a=line.rstrip('\n').split('\t'); d.setdefault(a[0],[]).append((int(a[1]),int(a[2]),int(a[3])))
    return d
def model2(s,h=1.0,minl=1,X=10.0):
    out=[]; sc=0.0; mx=0.0; mi=-1; start=-1; hits=0; sh=0; mh=0
    for i,c in enumerate(s):
        hit = c in 'GCS'
        if hit:
            if sc<=0: start=i; sh=hits
            hits+=1; sc+=h
        else:
            sc-=1.0
            if sc<0: sc=0.0
        if sc>mx: mx=sc; mi=i; mh=hits
        elif mx-sc>X:
            if mi+1-start>=minl: out.append((start,mi+1,mh-sh))
            sc=0.0; mx=0.0; mi=-1; start=-1
    if mx>0 and mi+1-start>=minl: out.append((start,mi+1,mh-sh))
    return out
if __name__=='__main__':
    d=load(sys.argv[1]); bad=0
    import itertools
    for L in range(1,11):
        for t in itertools.product('GA',repeat=L):
            s=''.join(t); exp=d.get(s,[]); got=model2(s)
            if exp!=got:
                bad+=1
                if bad<15: print(s,exp,got)
    print('bad',bad)
EOF
