def parse(fn):
    out=[]
    for line in open(fn):
        line=line.rstrip('\n')
        if line.startswith('>'): out.append([line[1:].split()[0],''])
        else: out[-1][1]+=line
    return out
def f32(x): return struct.unpack('f',struct.pack('f',x))[0]
def gc(recs, is_at=False, f=0.6, minl=20, x=10.0, ffloat=False):
