    return res
if __name__=='__main__':
    import ast
    recs=parse(sys.argv[1]); kw=ast.literal_eval(sys.argv[2]) if len(sys.argv)>2 else {}
    for r in gc(recs,**kw): print('%s\t%d\t%d\t%d'%r)
