#include "core.h"

/* ================= input stream ================= */

instream_t *in_from_gz(gzFile fp)
{
	instream_t *ks;
	if (fp == 0) return 0;
	ks = (instream_t*)calloc(1, sizeof(instream_t));
	ks->fp = fp;
	ks->buf = (unsigned char*)malloc(IN_BUFSIZE);
	return ks;
}

instream_t *in_open(const char *fn)
{
	gzFile fp;
	if (fn == 0) crash_segv();
	fp = strcmp(fn, "-") ? gzopen(fn, "r") : gzdopen(fileno(stdin), "r");
	return in_from_gz(fp);
}

void in_close(instream_t *ks)
{
	if (ks == 0) return;
	gzclose(ks->fp);
	free(ks->buf);
	free(ks);
}

static int in_fill(instream_t *ks)
{
	ks->begin = 0;
	ks->end = gzread(ks->fp, ks->buf, IN_BUFSIZE);
	if (ks->end == 0) { ks->is_eof = 1; return 0; }
	if (ks->end < 0) { ks->is_eof = 1; ks->end = 0; return -3; }
	return ks->end;
}

int in_getc(instream_t *ks)
{
	if (ks->is_eof && ks->begin >= ks->end) return -1;
	if (ks->begin >= ks->end) {
		int r = in_fill(ks);
		if (r == 0) return -1;
		if (r < 0) return -3;
	}
	return (int)ks->buf[ks->begin++];
}

int in_getuntil(instream_t *ks, int delimiter, str_t *str, int *dret, int append)
{
	int gotany = 0;
	if (dret) *dret = 0;
	str->l = append ? str->l : 0;
	for (;;) {
		int i;
		if (ks->begin >= ks->end) {
			if (!ks->is_eof) {
				int r = in_fill(ks);
				if (r == 0) break;
				if (r < 0) return -3;
			} else break;
		}
		if (delimiter == SEP_LINE) {
			unsigned char *sep = (unsigned char*)memchr(ks->buf + ks->begin, '\n', ks->end - ks->begin);
			i = sep != 0 ? (int)(sep - ks->buf) : ks->end;
		} else {
			for (i = ks->begin; i < ks->end; ++i)
				if (isspace(ks->buf[i])) break;
		}
		str_reserve(str, str->l + (i - ks->begin) + 1);
		gotany = 1;
		memcpy(str->s + str->l, ks->buf + ks->begin, i - ks->begin);
		str->l += i - ks->begin;
		ks->begin = i + 1;
		if (i < ks->end) {
			if (dret) *dret = ks->buf[i];
			break;
		}
	}
	if (!gotany && ks->is_eof && ks->begin >= ks->end) return -1;
	if (str->s == 0) {
		str->m = 1;
		str->s = (char*)calloc(1, 1);
	} else if (delimiter == SEP_LINE && str->l > 1 && str->s[str->l - 1] == '\r') --str->l;
	str->s[str->l] = 0;
	return (int)str->l;
}

/* ================= record reader ================= */

rec_t *rec_init(instream_t *ks)
{
	rec_t *r = (rec_t*)calloc(1, sizeof(rec_t));
	r->ks = ks;
	return r;
}

void rec_destroy(rec_t *r)
{
	if (r == 0) return;
	str_free(&r->name); str_free(&r->comment); str_free(&r->seq); str_free(&r->qual);
	free(r);
}

int rec_read(rec_t *r)
{
	int c, ret;
	instream_t *ks = r->ks;
	if (r->last_char == 0) {
		while ((c = in_getc(ks)) >= 0 && c != '>' && c != '@');
		if (c < 0) return c;
		r->last_char = c;
	}
	r->comment.l = r->seq.l = r->qual.l = 0;
	if ((ret = in_getuntil(ks, SEP_SPACE, &r->name, &c, 0)) < 0) return -1;
	if (c != '\n') in_getuntil(ks, SEP_LINE, &r->comment, 0, 0);
	if (r->seq.s == 0) {
		r->seq.m = 256;
		r->seq.s = (char*)malloc(r->seq.m);
	}
	while ((c = in_getc(ks)) >= 0 && c != '>' && c != '+' && c != '@') {
		if (c == '\n') continue;
		str_reserve(&r->seq, r->seq.l + 2);
		r->seq.s[r->seq.l++] = (char)c;
		in_getuntil(ks, SEP_LINE, &r->seq, 0, 1);
	}
	if (c == '>' || c == '@') r->last_char = c;
	str_reserve(&r->seq, r->seq.l + 1);
	r->seq.s[r->seq.l] = 0;
	r->is_fastq = (c == '+');
	if (!r->is_fastq) return (int)r->seq.l;
	if (r->qual.m < r->seq.m) {
		r->qual.m = r->seq.m;
		r->qual.s = (char*)realloc(r->qual.s, r->qual.m);
	}
	while ((c = in_getc(ks)) >= 0 && c != '\n');
	if (c == -1) return -2;
	while ((c = in_getuntil(ks, SEP_LINE, &r->qual, 0, 1)) >= 0 && r->qual.l < r->seq.l);
	if (c == -3) return -3;
	r->last_char = 0;
	if (r->seq.l != r->qual.l) return -2;
	return (int)r->seq.l;
}

