/* ================= output ================= */

void crash_segv(void)
{
	signal(SIGSEGV, SIG_DFL);
	raise(SIGSEGV);
	abort();
}

void crash_fpe(void)
{
	signal(SIGFPE, SIG_DFL);
	raise(SIGFPE);
	abort();
}

void fail_assert(const char *expr, int line, const char *func)
{
	fflush(stdout);
	fprintf(stderr, "%s: seqtk.c:%d: %s: Assertion `%s' failed.\n", program_invocation_short_name, line, func, expr);
	signal(SIGABRT, SIG_DFL);
	abort();
}

void out_str(FILE *fp, const str_t *s, unsigned line_len)
{
	if (line_len != UINT_MAX && line_len != 0) {
		size_t i;
		for (i = 0; i < s->l; i += line_len) {
			size_t n = s->l - i < line_len ? s->l - i : line_len;
			fputc('\n', fp);
			fwrite(s->s + i, 1, n, fp);
		}
		fputc('\n', fp);
	} else {
		fputc('\n', fp);
		if (s->s == 0) crash_segv();
		fputs(s->s, fp);
		fputc('\n', fp);
	}
}

void out_record(FILE *fp, const char *name, const char *suffix, const str_t *comment,
                const str_t *seq, const str_t *qual, unsigned line_len)
{
	fputc(qual->l ? '@' : '>', fp);
	if (name == 0) crash_segv();
	fputs(name, fp);
	if (suffix) fputs(suffix, fp);
	if (comment->l) {
		fputc(' ', fp);
		fputs(comment->s, fp);
	}
	out_str(fp, seq, line_len);
	if (qual->l) {
		fputc('+', fp);
		out_str(fp, qual, line_len);
	}
}

void out_wrapped60(FILE *fp, const char *s, size_t l)
{
	size_t i;
	for (i = 0; i < l; ++i) {
		if (i % 60 == 0) fputc('\n', fp);
		fputc(s[i], fp);
	}
	fputc('\n', fp);
}

/* ================= random numbers ================= */

#define MT_NN 312
#define MT_MM 156
#define MT_UM 0xFFFFFFFF80000000ULL
#define MT_LM 0x7FFFFFFFULL

void mt64_seed(mt64_t *r, uint64_t seed)
{
	int i;
	r->mt[0] = seed;
	for (i = 1; i < MT_NN; ++i)
		r->mt[i] = 6364136223846793005ULL * (r->mt[i-1] ^ (r->mt[i-1] >> 62)) + (uint64_t)i;
	r->mti = MT_NN;
}

uint64_t mt64_next(mt64_t *r)
{
	static const uint64_t mag01[2] = { 0ULL, 0xB5026F5AA96619E9ULL };
	uint64_t x;
	int i;
	if (r->mti >= MT_NN) {
		for (i = 0; i < MT_NN - MT_MM; ++i) {
			x = (r->mt[i] & MT_UM) | (r->mt[i+1] & MT_LM);
			r->mt[i] = r->mt[i+MT_MM] ^ (x >> 1) ^ mag01[(int)(x & 1ULL)];
		}
		for (; i < MT_NN - 1; ++i) {
			x = (r->mt[i] & MT_UM) | (r->mt[i+1] & MT_LM);
			r->mt[i] = r->mt[i+(MT_MM-MT_NN)] ^ (x >> 1) ^ mag01[(int)(x & 1ULL)];
		}
		x = (r->mt[MT_NN-1] & MT_UM) | (r->mt[0] & MT_LM);
		r->mt[MT_NN-1] = r->mt[MT_MM-1] ^ (x >> 1) ^ mag01[(int)(x & 1ULL)];
		r->mti = 0;
	}
	x = r->mt[r->mti++];
	x ^= (x >> 29) & 0x5555555555555555ULL;
	x ^= (x << 17) & 0x71D67FFFEDA60000ULL;
	x ^= (x << 37) & 0xFFF7EEE000000000ULL;
	x ^= (x >> 43);
	return x;
}

static uint64_t lcg_state = 0x1234ABCD330EULL;

void lcg48_seed(long seed)
{
	lcg_state = ((uint64_t)(uint32_t)seed << 16) | 0x330EULL;
}

static inline void lcg_step(void)
{
	lcg_state = (0x5DEECE66DULL * lcg_state + 0xBULL) & 0xFFFFFFFFFFFFULL;
}

long lcg48_lrand(void)
{
	lcg_step();
	return (long)(lcg_state >> 17);
}

double lcg48_drand(void)
{
	lcg_step();
	return (double)lcg_state / 281474976710656.0;
}

/* ================= regions ================= */

static uint32_t hash_str(const char *s)
{
	uint32_t h = 2166136261u;
	for (; *s; ++s) h = (h ^ (unsigned char)*s) * 16777619u;
	return h;
}

reghash_t *reg_new(void)
{
	reghash_t *h = (reghash_t*)calloc(1, sizeof(reghash_t));
	h->n_buckets = 1024;
	h->b = (reg_entry_t**)calloc(h->n_buckets, sizeof(reg_entry_t*));
	return h;
}

reg_entry_t *reg_get(reghash_t *h, const char *name)
{
	reg_entry_t *e;
	if (h == 0 || name == 0) return 0;
	for (e = h->b[hash_str(name) % h->n_buckets]; e; e = e->next)
		if (strcmp(e->name, name) == 0) return e;
	return 0;
}

reg_entry_t *reg_add(reghash_t *h, const char *name)
{
	reg_entry_t *e = reg_get(h, name);
	uint32_t k;
	if (e) return e;
	e = (reg_entry_t*)calloc(1, sizeof(reg_entry_t));
	e->name = strdup(name);
	k = hash_str(name) % h->n_buckets;
	e->next = h->b[k];
	h->b[k] = e;
	return e;
}

void reg_push(reg_entry_t *e, int64_t beg, int64_t end, int rev)
{
	if (e->n == e->m) {
		e->m = e->m ? e->m << 1 : 4;
		e->a = (reg_t*)realloc(e->a, e->m * sizeof(reg_t));
	}
	e->a[e->n].beg = beg;
	e->a[e->n].end = end;
	e->a[e->n].rev = rev;
	++e->n;
}

reghash_t *reg_read(const char *fn)
{
	instream_t *ks;
	reghash_t *h;
	str_t str = {0,0,0};
	int dret;
	ks = in_open(fn);
	if (ks == 0) return 0;
	h = reg_new();
	while (in_getuntil(ks, SEP_SPACE, &str, &dret, 0) >= 0) {
		int64_t beg = -1, end = -1;
		reg_entry_t *e = reg_add(h, str.s);
		if (dret != '\n') {
			if (in_getuntil(ks, SEP_SPACE, &str, &dret, 0) > 0 && isdigit((unsigned char)str.s[0])) {
				beg = atol(str.s);
				if (dret != '\n') {
					if (in_getuntil(ks, SEP_SPACE, &str, &dret, 0) > 0 && isdigit((unsigned char)str.s[0])) {
						end = atol(str.s);
						if (end < 0) end = -1;
					}
				}
			}
		}
		if (dret != '\n') while ((dret = in_getc(ks)) > 0 && dret != '\n');
		if (end < 0 && beg > 0) end = beg, beg = beg - 1;
		if (beg < 0) beg = 0, end = INT64_MAX;
		reg_push(e, beg, end, 0);
	}
	free(str.s);
	in_close(ks);
	return h;
}

static int all_digits(const char *s, size_t l)
{
	size_t i;
	if (l == 0) return 0;
	for (i = 0; i < l; ++i)
		if (!isdigit((unsigned char)s[i])) return 0;
	return 1;
}

reghash_t *reg_read_bed_tab(const char *fn)
{
	instream_t *ks;
	reghash_t *h;
	str_t line = {0,0,0};
	ks = in_open(fn);
	if (ks == 0) return 0;
	h = reg_new();
	while (in_getuntil(ks, SEP_LINE, &line, 0, 0) >= 0) {
		char *f[6];
		size_t fl[6];
		int nf = 0, rev = 0;
		size_t i, st = 0;
		int64_t beg = -1, end = -1;
		reg_entry_t *e;
		for (i = 0; i <= line.l && nf < 6; ++i) {
			if (i == line.l || line.s[i] == '\t') {
				f[nf] = line.s + st;
				fl[nf] = i - st;
				++nf;
				st = i + 1;
			}
		}
		for (i = 0; i < (size_t)nf; ++i) f[i][fl[i]] = 0;
		e = reg_add(h, f[0]);
		if (nf >= 2 && all_digits(f[1], fl[1])) {
			beg = atol(f[1]);
			if (nf >= 3 && all_digits(f[2], fl[2])) end = atol(f[2]);
		}
		if (nf >= 6 && f[5][0] == '-') rev = 1;
		if (end < 0 && beg > 0) end = beg, beg = beg - 1;
		if (beg < 0) beg = 0, end = INT64_MAX;
		reg_push(e, beg, end, rev);
	}
	free(line.s);
	in_close(ks);
	return h;
}
