/* ===================== comp ===================== */

static inline int is_clike(int x) { return x == 2 || x == 10; }
static inline int is_glike(int x) { return x == 4 || x == 5; }

static inline int comp_code(const char *s, int64_t l, int64_t i)
{
	unsigned char c = i < l ? (unsigned char)s[i] : 0;
	return nt16_tab[c];
}

static void comp_count(const char *s, int64_t l, int64_t beg, int64_t end, int upper_only, uint64_t cnt[11])
{
	int64_t i;
	memset(cnt, 0, 11 * sizeof(uint64_t));
	for (i = beg; i < end; ++i) {
		unsigned char raw = i < l ? (unsigned char)s[i] : 0;
		int x, b, cpg = 0;
		if (upper_only && !isupper(raw)) continue;
		x = nt16_tab[raw];
		if (x == 0) x = 15;
		b = popcnt4(x);
		if (b == 1) {
			if (x == 1) ++cnt[0];
			else if (x == 2) ++cnt[1];
			else if (x == 4) ++cnt[2];
			else ++cnt[3];
		} else ++cnt[2 + b];
		if (is_clike(x) && i + 1 < l && is_glike(comp_code(s, l, i + 1))) cpg = 1;
		if (is_glike(x) && i > 0 && i - 1 < l && is_clike(comp_code(s, l, i - 1))) cpg = 1;
		if (cpg) {
			++cnt[7];
			if (x == 5 || x == 10) ++cnt[10];
		}
		if (x == 5 || x == 10) ++cnt[9];
		if (x == 3 || x == 6 || x == 9 || x == 12) ++cnt[8];
	}
}

int cmd_comp(int argc, char *argv[])
{
	int c, upper_only = 0;
	reghash_t *h = 0;
	instream_t *ks;
	rec_t *r;
	while ((c = getopt(argc, argv, "ur:")) >= 0) {
		switch (c) {
		case 'u': upper_only = 1; break;
		case 'r': h = reg_read(optarg); break;
		default: break;
		}
	}
	if (argc == optind && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage:  seqtk comp [-u] [-r in.bed] <in.fa>\n\n");
		fprintf(stderr, "Output format: chr, length, #A, #C, #G, #T, #2, #3, #4, #CpG, #tv, #ts, #CpG-ts\n");
		return 1;
	}
	ks = in_open(optind < argc ? argv[optind] : "-");
	if (ks == 0) {
		OPEN_FAIL("stk_comp");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		uint64_t cnt[11];
		int k;
		if (h == 0) {
			comp_count(r->seq.s, (int64_t)r->seq.l, 0, (int64_t)r->seq.l, upper_only, cnt);
			printf("%s\t%ld", r->name.s, (long)r->seq.l);
			for (k = 0; k < 11; ++k) printf("\t%lu", (unsigned long)cnt[k]);
			putchar('\n');
			fflush(stdout);
		} else {
			reg_entry_t *e = reg_get(h, r->name.s);
			size_t j;
			if (e == 0) continue;
			for (j = 0; j < e->n; ++j) {
				int64_t b = e->a[j].beg, en = e->a[j].end;
				if (en > (int64_t)r->seq.l + 65536 && en > b) crash_segv();
				comp_count(r->seq.s, (int64_t)r->seq.l, b, en, upper_only, cnt);
				printf("%s\t%ld\t%ld", r->name.s, (long)b, (long)en);
				for (k = 0; k < 11; ++k) printf("\t%lu", (unsigned long)cnt[k]);
				putchar('\n');
				fflush(stdout);
			}
		}
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== sample ===================== */

static void sample_usage(void)
{
	fprintf(stderr, "\n");
	fprintf(stderr, "Usage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\n");
	fprintf(stderr, "Options: -s INT       RNG seed [11]\n");
	fprintf(stderr, "         -2           2-pass mode: twice as slow but with much reduced memory\n\n");
}

typedef struct { str_t name, comment, seq, qual; } slot_t;

static int cmp_u64(const void *a, const void *b)
{
	uint64_t x = *(const uint64_t*)a, y = *(const uint64_t*)b;
	return x < y ? -1 : x > y ? 1 : 0;
}

int cmd_sample(int argc, char *argv[])
{
	int c, twopass = 0;
	long seed = 11;
	double frac;
	uint64_t num = 0, n = 0, i;
	instream_t *ks;
	rec_t *r;
	mt64_t rng;
	const char *fn;
	while ((c = getopt(argc, argv, "2s:")) >= 0) {
		switch (c) {
		case '2': twopass = 1; break;
		case 's': seed = atol(optarg); break;
		default: sample_usage(); return 1;
		}
	}
	if (optind + 2 > argc) {
		sample_usage();
		return 1;
	}
	fn = argv[optind];
	frac = atof(argv[optind + 1]);
	if (frac >= 1.0) num = (uint64_t)(frac + .499), frac = 0.;
	else if (twopass) {
		fprintf(stderr, "[W::stk_sample] when sampling a fraction, option -2 is ignored.\n");
		twopass = 0;
	}
	if (twopass && strcmp(fn, "-") == 0) {
		fprintf(stderr, "[E::stk_sample] in the 2-pass mode, the input cannot be STDIN.\n");
		return 1;
	}
	ks = in_open(fn);
	if (ks == 0) {
		OPEN_FAIL("stk_sample");
		return 1;
	}
	r = rec_init(ks);
	mt64_seed(&rng, (uint64_t)seed);
	if (num == 0) {
		while (rec_read(r) >= 0) {
			double x = mt64_drand(&rng);
			if (x < frac) out_rec(stdout, r, UINT_MAX);
		}
	} else if (!twopass) {
		slot_t *buf = (slot_t*)calloc(num < 1000000 ? num : 1000000, sizeof(slot_t));
		uint64_t cap = num < 1000000 ? num : 1000000;
		while (rec_read(r) >= 0) {
			double x = mt64_drand(&rng);
			uint64_t y = n < num ? n : (uint64_t)(x * (double)(n + 1));
			if (y < num) {
				slot_t *p;
				if (y >= cap) {
					uint64_t nc = cap;
					while (nc <= y) nc <<= 1;
					if (nc > num) nc = num;
					buf = (slot_t*)realloc(buf, nc * sizeof(slot_t));
					memset(buf + cap, 0, (nc - cap) * sizeof(slot_t));
					cap = nc;
				}
				p = &buf[y];
				str_copy_nonempty(&p->name, &r->name);
				str_copy_nonempty(&p->comment, &r->comment);
				str_copy_nonempty(&p->seq, &r->seq);
				str_copy_nonempty(&p->qual, &r->qual);
			}
			++n;
		}
		for (i = 0; i < num && i < cap; ++i) {
			slot_t *p = &buf[i];
			if (p->seq.l)
				out_record(stdout, p->name.s, 0, &p->comment, &p->seq, &p->qual, UINT_MAX);
		}
	} else {
		uint64_t cap = num < 1000000 ? num : 1000000, m;
		uint64_t *idx = (uint64_t*)malloc(cap * sizeof(uint64_t));
		while (rec_read(r) >= 0) {
			double x = mt64_drand(&rng);
			uint64_t y = n < num ? n : (uint64_t)(x * (double)(n + 1));
			if (y < num) {
				if (y >= cap) {
					uint64_t nc = cap;
					while (nc <= y) nc <<= 1;
					if (nc > num) nc = num;
					idx = (uint64_t*)realloc(idx, nc * sizeof(uint64_t));
					cap = nc;
				}
				idx[y] = n;
			}
			++n;
		}
		m = n < num ? n : num;
		qsort(idx, m, sizeof(uint64_t), cmp_u64);
		rec_destroy(r);
		in_close(ks);
		ks = in_open(fn);
		if (ks == 0) {
			OPEN_FAIL("stk_sample");
			return 1;
		}
		r = rec_init(ks);
		n = 0; i = 0;
		while (i < m && rec_read(r) >= 0) {
			if (n == idx[i]) {
				out_rec(stdout, r, UINT_MAX);
				++i;
			}
			++n;
		}
		free(idx);
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== subseq ===================== */

static void subseq_usage(int line_len)
{
	fprintf(stderr, "Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\n");
	fprintf(stderr, "Options:\n");
	fprintf(stderr, "  -t       TAB delimited output\n");
	fprintf(stderr, "  -s       strand aware\n");
	fprintf(stderr, "  -l INT   sequence line length [%d]\n", line_len);
	fprintf(stderr, "Note: Use 'samtools faidx' if only a few regions are intended.\n");
}

static void out_region(const char *s, int64_t beg, int64_t end, int line_len)
{
	int64_t i;
	if (line_len <= 0) {
		if (end > beg) {
			fwrite(s + beg, 1, (size_t)(end - beg), stdout);
			putchar('\n');
		}
		return;
	}
	for (i = beg; i < end; i += line_len) {
		int64_t n = end - i < line_len ? end - i : line_len;
		fwrite(s + i, 1, (size_t)n, stdout);
		putchar('\n');
	}
}

int cmd_subseq(int argc, char *argv[])
{
	int c, is_tab = 0, is_strand = 0, line_len = 0;
	reghash_t *h;
	instream_t *ks;
	rec_t *r;
	str_t tmp = {0,0,0};
	while ((c = getopt(argc, argv, "tsl:")) >= 0) {
		switch (c) {
		case 't': is_tab = 1; break;
		case 's': is_strand = 1; break;
		case 'l': line_len = atoi(optarg); break;
		default: subseq_usage(line_len); return 1;
		}
	}
	if (optind + 2 > argc) {
		subseq_usage(line_len);
		return 1;
	}
	h = is_strand ? reg_read_bed_tab(argv[optind + 1]) : reg_read(argv[optind + 1]);
	if (h == 0) {
		fprintf(stderr, "[E::stk_subseq] failed to read the list of regions in file '%s'\n", argv[optind + 1]);
		return 1;
	}
	ks = in_open(argv[optind]);
	if (ks == 0) {
		fprintf(stderr, "[E::stk_subseq] failed to open the input file/stream\n");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		reg_entry_t *e = reg_get(h, r->name.s);
		size_t j;
		if (e == 0) continue;
		for (j = 0; j < e->n; ++j) {
			int64_t beg = e->a[j].beg, end = e->a[j].end, oend = end;
			int64_t l = (int64_t)r->seq.l;
			if (beg >= l) {
				fprintf(stderr, "[subseq] %s: %ld >= %ld\n", r->name.s, (long)beg, (long)l);
				continue;
			}
			if (end > l) end = l;
			if (is_strand) {
				int64_t k, n = end > beg ? end - beg : 0;
				tmp.l = 0;
				str_reserve(&tmp, (size_t)n + 1);
				if (e->a[j].rev) {
					for (k = 0; k < n; ++k)
						tmp.s[k] = (char)comp_tab[(unsigned char)r->seq.s[end - 1 - k]];
				} else memcpy(tmp.s, r->seq.s + beg, (size_t)n);
				tmp.s[n] = 0; tmp.l = (size_t)n;
				if (is_tab) {
					printf("%s\t%ld\t\n", r->name.s, (long)(beg + 1));
				} else {
					putchar(r->qual.l ? '@' : '>');
					fputs(r->name.s, stdout);
					if (beg > 0 || oend != INT64_MAX) printf(":%ld-%ld", (long)(beg + 1), (long)end);
					if (r->comment.l) { putchar(' '); fputs(r->comment.s, stdout); }
					putchar('\n');
				}
				fwrite(tmp.s, 1, tmp.l, stdout);
				putchar('\n');
			} else if (is_tab) {
				printf("%s\t%ld\t", r->name.s, (long)(beg + 1));
				if (end > beg) fwrite(r->seq.s + beg, 1, (size_t)(end - beg), stdout);
				putchar('\n');
			} else {
				putchar(r->qual.l ? '@' : '>');
				fputs(r->name.s, stdout);
				if (beg > 0 || oend != INT64_MAX) printf(":%ld-%ld", (long)(beg + 1), (long)end);
				if (r->comment.l) { putchar(' '); fputs(r->comment.s, stdout); }
				putchar('\n');
				out_region(r->seq.s, beg, end, line_len);
				if (r->qual.l) {
					puts("+");
					out_region(r->qual.s, beg, end, line_len);
				}
			}
		}
	}
	free(tmp.s);
	rec_destroy(r);
	in_close(ks);
	return 0;
}
