#include "core.h"
#include "cmds.h"

#define OPEN_FAIL(func) fprintf(stderr, "[E::%s] failed to open the input file/stream.\n", func)

/* ===================== seq ===================== */

static void seq_usage(int line_len, int qshift)
{
	fprintf(stderr, "\n");
	fprintf(stderr, "Usage:   seqtk seq [options] <in.fq>|<in.fa>\n\n");
	fprintf(stderr, "Options: -q INT    mask bases with quality lower than INT [0]\n");
	fprintf(stderr, "         -X INT    mask bases with quality higher than INT [255]\n");
	fprintf(stderr, "         -n CHAR   masked bases converted to CHAR; 0 for lowercase [0]\n");
	fprintf(stderr, "         -l INT    number of residues per line; 0 for 2^32-1 [%d]\n", line_len);
	fprintf(stderr, "         -Q INT    quality shift: ASCII-INT gives base quality [%d]\n", qshift);
	fprintf(stderr, "         -s INT    random seed (effective with -f) [11]\n");
	fprintf(stderr, "         -f FLOAT  sample FLOAT fraction of sequences [1]\n");
	fprintf(stderr, "         -M FILE   mask regions in BED or name list FILE [null]\n");
	fprintf(stderr, "         -L INT    drop sequences with length shorter than INT [0]\n");
	fprintf(stderr, "         -F CHAR   fake FASTQ quality []\n");
	fprintf(stderr, "         -c        mask complement region (effective with -M)\n");
	fprintf(stderr, "         -r        reverse complement\n");
	fprintf(stderr, "         -R        output both forward and reverse complement\n");
	fprintf(stderr, "         -A        force FASTA output (discard quality)\n");
	fprintf(stderr, "         -C        drop comments at the header lines\n");
	fprintf(stderr, "         -N        drop sequences containing ambiguous bases\n");
	fprintf(stderr, "         -1        output the 2n-1 reads only\n");
	fprintf(stderr, "         -2        output the 2n reads only\n");
	fprintf(stderr, "         -V        shift quality by '(-Q) - 33'\n");
	fprintf(stderr, "         -U        convert all bases to uppercases\n");
	fprintf(stderr, "         -x        convert all lowercases to -n\n");
	fprintf(stderr, "         -S        strip of white spaces in sequences\n");
	fprintf(stderr, "\n");
}

static void revcomp_rec(rec_t *r)
{
	size_t i, l = r->seq.l;
	char *s = r->seq.s;
	for (i = 0; i < l >> 1; ++i) {
		unsigned char a = (unsigned char)s[i], b = (unsigned char)s[l - 1 - i];
		s[i] = (char)comp_tab[b];
		s[l - 1 - i] = (char)comp_tab[a];
	}
	if (l & 1) s[l >> 1] = (char)comp_tab[(unsigned char)s[l >> 1]];
	if (r->qual.l) {
		char *q = r->qual.s;
		size_t lq = r->qual.l;
		for (i = 0; i < lq >> 1; ++i) {
			char t = q[i];
			q[i] = q[lq - 1 - i];
			q[lq - 1 - i] = t;
		}
	}
}

static inline char mask_base(char c, int mask_chr)
{
	return mask_chr ? (char)mask_chr : (char)tolower((unsigned char)c);
}

static void print_seq_opts(rec_t *r, const char *suffix, int fasta, int no_comment, unsigned line_len)
{
	str_t empty = {0,0,0};
	const str_t *comment = no_comment ? &empty : &r->comment;
	const str_t *qual = fasta ? &empty : &r->qual;
	out_record(stdout, r->name.s, suffix, comment, &r->seq, qual, line_len);
}

int cmd_seq(int argc, char *argv[])
{
	int c, qual_thres = 0, max_qual = 255, mask_chr = 0, line_len = 0, qshift = 33, min_len = 0, fake_qual = 0;
	int is_fasta = 0, no_comment = 0, mask_comp = 0, is_rev = 0, is_both = 0, drop_amb = 0, flag12 = 0;
	int shift_qual = 0, to_upper = 0, low2mask = 0, strip_ws = 0;
	long seed = 11;
	double frac = 1.0;
	reghash_t *mask = 0;
	instream_t *ks;
	rec_t *r;
	mt64_t rng;
	uint64_t n = 0;
	unsigned char *keep = 0;
	size_t keep_m = 0;

	while ((c = getopt(argc, argv, "N12q:l:Q:aACrRF:s:f:M:L:cVUX:Sxn:")) >= 0) {
		switch (c) {
		case 'a': case 'A': is_fasta = 1; break;
		case 'C': no_comment = 1; break;
		case 'c': mask_comp = 1; break;
		case 'r': is_rev = 1; break;
		case 'R': is_both = 1; break;
		case 'N': drop_amb = 1; break;
		case '1': flag12 |= 1; break;
		case '2': flag12 |= 2; break;
		case 'V': shift_qual = 1; break;
		case 'U': to_upper = 1; break;
		case 'S': strip_ws = 1; break;
		case 'x': low2mask = 1; break;
		case 'q': qual_thres = atoi(optarg); break;
		case 'X': max_qual = atoi(optarg); break;
		case 'l': line_len = atoi(optarg); break;
		case 'Q': qshift = atoi(optarg); break;
		case 's': seed = atol(optarg); break;
		case 'f': frac = atof(optarg); break;
		case 'M': mask = reg_read(optarg); break;
		case 'L': min_len = atoi(optarg); break;
		case 'F': fake_qual = optarg[0]; break;
		case 'n': mask_chr = optarg[0]; break;
		default: break;
		}
	}
	if (argc == optind && isatty(fileno(stdin))) {
		seq_usage(line_len, qshift);
		return 1;
	}
	ks = in_open(optind < argc ? argv[optind] : "-");
	if (ks == 0) {
		OPEN_FAIL("stk_seq");
		return 1;
	}
	r = rec_init(ks);
	mt64_seed(&rng, (uint64_t)seed);
	while (rec_read(r) >= 0) {
		size_t i;
		++n;
		if (r->seq.l < (size_t)(long)min_len && (long)r->seq.l < (long)min_len) continue;
		if (frac < 1.0 && mt64_drand(&rng) >= frac) continue;
		if ((flag12 & 1) && (n & 1) == 0) continue;
		if ((flag12 & 2) && (n & 1) == 1) continue;
		if (strip_ws) {
			size_t k = 0;
			for (i = 0; i < r->seq.l; ++i) {
				if (isspace((unsigned char)r->seq.s[i])) continue;
				r->seq.s[k] = r->seq.s[i];
				if (r->qual.l) r->qual.s[k] = r->qual.s[i];
				++k;
			}
			r->seq.l = k;
			if (r->qual.l) r->qual.l = k;
		}
		if (qual_thres > 0 && r->qual.l) {
			for (i = 0; i < r->qual.l; ++i) {
				int q = (signed char)r->qual.s[i];
				if (q - qshift < qual_thres || q > max_qual)
					r->seq.s[i] = mask_base(r->seq.s[i], mask_chr);
			}
		}
		if (to_upper)
			for (i = 0; i < r->seq.l; ++i) r->seq.s[i] = (char)toupper((unsigned char)r->seq.s[i]);
		if (mask) {
			reg_entry_t *e = reg_get(mask, r->name.s);
			if (!mask_comp) {
				if (e) {
					size_t j;
					for (j = 0; j < e->n; ++j) {
						int64_t b = e->a[j].beg, en = e->a[j].end, k;
						if (en > (int64_t)r->seq.l) en = (int64_t)r->seq.l;
						for (k = b < 0 ? 0 : b; k < en; ++k)
							r->seq.s[k] = mask_base(r->seq.s[k], mask_chr);
					}
				}
			} else {
				if (keep_m < r->seq.l + 1) {
					keep_m = r->seq.l + 1;
					keep = (unsigned char*)realloc(keep, keep_m);
				}
				memset(keep, 0, r->seq.l + 1);
				if (e) {
					size_t j;
					for (j = 0; j < e->n; ++j) {
						int64_t b = e->a[j].beg, en = e->a[j].end, k;
						if (en > (int64_t)r->seq.l) en = (int64_t)r->seq.l;
						for (k = b < 0 ? 0 : b; k < en; ++k) keep[k] = 1;
					}
				}
				for (i = 0; i < r->seq.l; ++i)
					if (!keep[i]) r->seq.s[i] = mask_base(r->seq.s[i], mask_chr);
			}
		}
		if (low2mask && mask_chr)
			for (i = 0; i < r->seq.l; ++i)
				if (islower((unsigned char)r->seq.s[i])) r->seq.s[i] = (char)mask_chr;
		if (fake_qual && r->seq.l) {
			str_reserve(&r->qual, r->seq.l + 1);
			memset(r->qual.s, fake_qual, r->seq.l);
			r->qual.s[r->seq.l] = 0;
			r->qual.l = r->seq.l;
		}
		if (is_both) print_seq_opts(r, "+", is_fasta, no_comment, (unsigned)line_len);
		if (drop_amb) {
			for (i = 0; i < r->seq.l; ++i)
				if (nt4_tab[(unsigned char)r->seq.s[i]] > 3) break;
			if (i < r->seq.l) continue;
		}
		if (is_rev || is_both) revcomp_rec(r);
		if (shift_qual && r->qual.l) {
			int d = qshift - 33;
			for (i = 0; i < r->qual.l; ++i) r->qual.s[i] = (char)(r->qual.s[i] - d);
		}
		print_seq_opts(r, is_both ? "-" : 0, is_fasta, no_comment, (unsigned)line_len);
	}
	free(keep);
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== size ===================== */

int cmd_size(int argc, char *argv[])
{
	instream_t *ks;
	rec_t *r;
	uint64_t n = 0, tot = 0;
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk size <in.fq>\n");
		return 1;
	}
	ks = in_open(argc > 1 ? argv[1] : "-");
	if (ks == 0) {
		OPEN_FAIL("stk_size");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		++n;
		tot += r->seq.l;
	}
	printf("%llu\t%llu\n", (unsigned long long)n, (unsigned long long)tot);
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== comp ===================== */

static inline int is_clike(int x) { return x == 2 || x == 10; }
static inline int is_glike(int x) { return x == 4 || x == 5; }

static inline int comp_code(const char *s, int64_t l, int64_t i)
{
	unsigned char c = i < l ? (unsigned char)s[i] : 0;
	return nt16_tab[c];
}

static void comp_count(const char *s, int64_t l, int64_t beg, int64_t end, int upper_only, uint64_t cnt[11])
{
	int64_t i;
	memset(cnt, 0, 11 * sizeof(uint64_t));
	for (i = beg; i < end; ++i) {
		unsigned char raw = i < l ? (unsigned char)s[i] : 0;
		int x, b, cpg = 0;
		if (upper_only && !isupper(raw)) continue;
		x = nt16_tab[raw];
		if (x == 0) x = 15;
		b = popcnt4(x);
		if (b == 1) {
			if (x == 1) ++cnt[0];
			else if (x == 2) ++cnt[1];
			else if (x == 4) ++cnt[2];
			else ++cnt[3];
		} else ++cnt[2 + b];
		if (is_clike(x) && i + 1 < l && is_glike(comp_code(s, l, i + 1))) cpg = 1;
		if (is_glike(x) && i > 0 && i - 1 < l && is_clike(comp_code(s, l, i - 1))) cpg = 1;
		if (cpg) {
			++cnt[7];
			if (x == 5 || x == 10) ++cnt[10];
		}
		if (x == 5 || x == 10) ++cnt[9];
		if (x == 3 || x == 6 || x == 9 || x == 12) ++cnt[8];
	}
}

int cmd_comp(int argc, char *argv[])
{
	int c, upper_only = 0;
	reghash_t *h = 0;
	instream_t *ks;
	rec_t *r;
	while ((c = getopt(argc, argv, "ur:")) >= 0) {
		switch (c) {
		case 'u': upper_only = 1; break;
		case 'r': h = reg_read(optarg); break;
		default: break;
		}
	}
	if (argc == optind && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage:  seqtk comp [-u] [-r in.bed] <in.fa>\n\n");
		fprintf(stderr, "Output format: chr, length, #A, #C, #G, #T, #2, #3, #4, #CpG, #tv, #ts, #CpG-ts\n");
		return 1;
	}
	ks = in_open(optind < argc ? argv[optind] : "-");
	if (ks == 0) {
		OPEN_FAIL("stk_comp");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		uint64_t cnt[11];
		int k;
		if (h == 0) {
			comp_count(r->seq.s, (int64_t)r->seq.l, 0, (int64_t)r->seq.l, upper_only, cnt);
			printf("%s\t%ld", r->name.s, (long)r->seq.l);
			for (k = 0; k < 11; ++k) printf("\t%lu", (unsigned long)cnt[k]);
			putchar('\n');
			fflush(stdout);
		} else {
			reg_entry_t *e = reg_get(h, r->name.s);
			size_t j;
			if (e == 0) continue;
			for (j = 0; j < e->n; ++j) {
				int64_t b = e->a[j].beg, en = e->a[j].end;
				if (en > (int64_t)r->seq.l + 65536 && en > b) crash_segv();
				comp_count(r->seq.s, (int64_t)r->seq.l, b, en, upper_only, cnt);
				printf("%s\t%ld\t%ld", r->name.s, (long)b, (long)en);
				for (k = 0; k < 11; ++k) printf("\t%lu", (unsigned long)cnt[k]);
				putchar('\n');
				fflush(stdout);
			}
		}
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== sample ===================== */

static void sample_usage(void)
{
	fprintf(stderr, "\n");
	fprintf(stderr, "Usage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\n");
	fprintf(stderr, "Options: -s INT       RNG seed [11]\n");
	fprintf(stderr, "         -2           2-pass mode: twice as slow but with much reduced memory\n\n");
}

typedef struct { str_t name, comment, seq, qual; } slot_t;

static int cmp_u64(const void *a, const void *b)
{
	uint64_t x = *(const uint64_t*)a, y = *(const uint64_t*)b;
	return x < y ? -1 : x > y ? 1 : 0;
}

int cmd_sample(int argc, char *argv[])
{
	int c, twopass = 0;
	long seed = 11;
	double frac;
	uint64_t num = 0, n = 0, i;
	instream_t *ks;
	rec_t *r;
	mt64_t rng;
	const char *fn;
	while ((c = getopt(argc, argv, "2s:")) >= 0) {
		switch (c) {
		case '2': twopass = 1; break;
		case 's': seed = atol(optarg); break;
		default: sample_usage(); return 1;
		}
	}
	if (optind + 2 > argc) {
		sample_usage();
		return 1;
	}
	fn = argv[optind];
	frac = atof(argv[optind + 1]);
	if (frac >= 1.0) num = (uint64_t)(frac + .499), frac = 0.;
	else if (twopass) {
		fprintf(stderr, "[W::stk_sample] when sampling a fraction, option -2 is ignored.\n");
		twopass = 0;
	}
	if (twopass && strcmp(fn, "-") == 0) {
		fprintf(stderr, "[E::stk_sample] in the 2-pass mode, the input cannot be STDIN.\n");
		return 1;
	}
	ks = in_open(fn);
	if (ks == 0) {
		OPEN_FAIL("stk_sample");
		return 1;
	}
	r = rec_init(ks);
	mt64_seed(&rng, (uint64_t)seed);
	if (num == 0) {
		while (rec_read(r) >= 0) {
			double x = mt64_drand(&rng);
			if (x < frac) out_rec(stdout, r, UINT_MAX);
		}
	} else if (!twopass) {
		slot_t *buf = (slot_t*)calloc(num < 1000000 ? num : 1000000, sizeof(slot_t));
		uint64_t cap = num < 1000000 ? num : 1000000;
		while (rec_read(r) >= 0) {
			double x = mt64_drand(&rng);
			uint64_t y = n < num ? n : (uint64_t)(x * (double)(n + 1));
			if (y < num) {
				slot_t *p;
				if (y >= cap) {
					uint64_t nc = cap;
					while (nc <= y) nc <<= 1;
					if (nc > num) nc = num;
					buf = (slot_t*)realloc(buf, nc * sizeof(slot_t));
					memset(buf + cap, 0, (nc - cap) * sizeof(slot_t));
					cap = nc;
				}
				p = &buf[y];
				str_copy_nonempty(&p->name, &r->name);
				str_copy_nonempty(&p->comment, &r->comment);
				str_copy_nonempty(&p->seq, &r->seq);
				str_copy_nonempty(&p->qual, &r->qual);
			}
			++n;
		}
		for (i = 0; i < num && i < cap; ++i) {
			slot_t *p = &buf[i];
			if (p->seq.l)
				out_record(stdout, p->name.s, 0, &p->comment, &p->seq, &p->qual, UINT_MAX);
		}
	} else {
		uint64_t cap = num < 1000000 ? num : 1000000, m;
		uint64_t *idx = (uint64_t*)malloc(cap * sizeof(uint64_t));
		while (rec_read(r) >= 0) {
			double x = mt64_drand(&rng);
			uint64_t y = n < num ? n : (uint64_t)(x * (double)(n + 1));
			if (y < num) {
				if (y >= cap) {
					uint64_t nc = cap;
					while (nc <= y) nc <<= 1;
					if (nc > num) nc = num;
					idx = (uint64_t*)realloc(idx, nc * sizeof(uint64_t));
					cap = nc;
				}
				idx[y] = n;
			}
			++n;
		}
		m = n < num ? n : num;
		qsort(idx, m, sizeof(uint64_t), cmp_u64);
		rec_destroy(r);
		in_close(ks);
		ks = in_open(fn);
		if (ks == 0) {
			OPEN_FAIL("stk_sample");
			return 1;
		}
		r = rec_init(ks);
		n = 0; i = 0;
		while (i < m && rec_read(r) >= 0) {
			if (n == idx[i]) {
				out_rec(stdout, r, UINT_MAX);
				++i;
			}
			++n;
		}
		free(idx);
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== subseq ===================== */

static void subseq_usage(int line_len)
{
	fprintf(stderr, "Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\n");
	fprintf(stderr, "Options:\n");
	fprintf(stderr, "  -t       TAB delimited output\n");
	fprintf(stderr, "  -s       strand aware\n");
	fprintf(stderr, "  -l INT   sequence line length [%d]\n", line_len);
	fprintf(stderr, "Note: Use 'samtools faidx' if only a few regions are intended.\n");
}

static void out_region(const char *s, int64_t beg, int64_t end, int line_len)
{
	int64_t i;
	if (line_len <= 0) {
		if (end > beg) {
			fwrite(s + beg, 1, (size_t)(end - beg), stdout);
			putchar('\n');
		}
		return;
	}
	for (i = beg; i < end; i += line_len) {
		int64_t n = end - i < line_len ? end - i : line_len;
		fwrite(s + i, 1, (size_t)n, stdout);
		putchar('\n');
	}
}

int cmd_subseq(int argc, char *argv[])
{
	int c, is_tab = 0, is_strand = 0, line_len = 0;
	reghash_t *h;
	instream_t *ks;
	rec_t *r;
	str_t tmp = {0,0,0};
	while ((c = getopt(argc, argv, "tsl:")) >= 0) {
		switch (c) {
		case 't': is_tab = 1; break;
		case 's': is_strand = 1; break;
		case 'l': line_len = atoi(optarg); break;
		default: subseq_usage(line_len); return 1;
		}
	}
	if (optind + 2 > argc) {
		subseq_usage(line_len);
		return 1;
	}
	h = is_strand ? reg_read_bed_tab(argv[optind + 1]) : reg_read(argv[optind + 1]);
	if (h == 0) {
		fprintf(stderr, "[E::stk_subseq] failed to read the list of regions in file '%s'\n", argv[optind + 1]);
		return 1;
	}
	ks = in_open(argv[optind]);
	if (ks == 0) {
		fprintf(stderr, "[E::stk_subseq] failed to open the input file/stream\n");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		reg_entry_t *e = reg_get(h, r->name.s);
		size_t j;
		if (e == 0) continue;
		for (j = 0; j < e->n; ++j) {
			int64_t beg = e->a[j].beg, end = e->a[j].end, oend = end;
			int64_t l = (int64_t)r->seq.l;
			if (beg >= l) {
				fprintf(stderr, "[subseq] %s: %ld >= %ld\n", r->name.s, (long)beg, (long)l);
				continue;
			}
			if (end > l) end = l;
			if (is_strand) {
				int64_t k, n = end > beg ? end - beg : 0;
				tmp.l = 0;
				str_reserve(&tmp, (size_t)n + 1);
				if (e->a[j].rev) {
					for (k = 0; k < n; ++k)
						tmp.s[k] = (char)comp_tab[(unsigned char)r->seq.s[end - 1 - k]];
				} else memcpy(tmp.s, r->seq.s + beg, (size_t)n);
				tmp.s[n] = 0; tmp.l = (size_t)n;
				if (is_tab) {
					printf("%s\t%ld\t\n", r->name.s, (long)(beg + 1));
				} else {
					putchar(r->qual.l ? '@' : '>');
					fputs(r->name.s, stdout);
					if (beg > 0 || oend != INT64_MAX) printf(":%ld-%ld", (long)(beg + 1), (long)end);
					if (r->comment.l) { putchar(' '); fputs(r->comment.s, stdout); }
					putchar('\n');
				}
				fwrite(tmp.s, 1, tmp.l, stdout);
				putchar('\n');
			} else if (is_tab) {
				printf("%s\t%ld\t", r->name.s, (long)(beg + 1));
				if (end > beg) fwrite(r->seq.s + beg, 1, (size_t)(end - beg), stdout);
				putchar('\n');
			} else {
				putchar(r->qual.l ? '@' : '>');
				fputs(r->name.s, stdout);
				if (beg > 0 || oend != INT64_MAX) printf(":%ld-%ld", (long)(beg + 1), (long)end);
				if (r->comment.l) { putchar(' '); fputs(r->comment.s, stdout); }
				putchar('\n');
				out_region(r->seq.s, beg, end, line_len);
				if (r->qual.l) {
					puts("+");
					out_region(r->qual.s, beg, end, line_len);
				}
			}
		}
	}
	free(tmp.s);
	rec_destroy(r);
	in_close(ks);
	return 0;
}
