/* ===================== split ===================== */

static void split_usage(int n, int l)
{
	fprintf(stderr, "Usage: seqtk split [options] <prefix> <in.fa>\n");
	fprintf(stderr, "Options:\n");
	fprintf(stderr, "  -n INT    number of files [%d]\n", n);
	fprintf(stderr, "  -l INT    line length [%d]\n", l);
}

int cmd_split(int argc, char *argv[])
{
	int c, nf = 10, line_len = 0, i;
	instream_t *ks;
	rec_t *r;
