/* ===================== trimfq ===================== */

static void trimfq_usage(double q, int l, int b, int e, int L)
{
	fprintf(stderr, "\n");
	fprintf(stderr, "Usage:   seqtk trimfq [options] <in.fq>\n\n");
	fprintf(stderr, "Options: -q FLOAT    error rate threshold (disabled by -b/-e) [%.2f]\n", q);
	fprintf(stderr, "         -l INT      maximally trim down to INT bp (disabled by -b/-e) [%d]\n", l);
	fprintf(stderr, "         -b INT      trim INT bp from left (non-zero to disable -q/-l) [%d]\n", b);
	fprintf(stderr, "         -e INT      trim INT bp from right (non-zero to disable -q/-l) [%d]\n", e);
	fprintf(stderr, "         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [%d]\n", L);
	fprintf(stderr, "         -Q          force FASTQ output\n");
	fprintf(stderr, "\n");
}

int cmd_trimfq(int argc, char *argv[])
{
	int c, min_len = 30, left = 0, right = 0, fixed_len = 0, i;
	double param = 0.05, q_int2real[128];
	instream_t *ks;
	rec_t *r;
	while ((c = getopt(argc, argv, "l:q:b:e:L:")) >= 0) {
		switch (c) {
		case 'q': param = atof(optarg); break;
		case 'l': min_len = atoi(optarg); break;
		case 'b': left = atoi(optarg); break;
		case 'e': right = atoi(optarg); break;
		case 'L': fixed_len = atoi(optarg); break;
		default: break;
		}
	}
	if (optind == argc) {
		trimfq_usage(param, min_len, left, right, fixed_len);
		return 1;
	}
	ks = in_open(argv[optind]);
	if (ks == 0) {
		OPEN_FAIL("stk_trimfq");
		return 1;
	}
	for (i = 0; i < 128; ++i) q_int2real[i] = pow(10.0, -(i - 33) / 10.0);
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		int64_t beg, end, l = (int64_t)r->seq.l;
		if (left || right || fixed_len) {
			beg = left; end = l - right;
			if (fixed_len > 0 && end - beg > fixed_len) end = beg + fixed_len;
			if (beg < 0) beg = 0;
			if (end > l) end = l;
			if (beg >= end) beg = end = 0;
		} else if (r->qual.l > (size_t)(long)min_len) {
			int64_t tmp = 0, k;
			double s = 0., max = 0.;
			beg = end = 0;
			for (k = 0; k < l; ++k) {
				int q = (signed char)r->qual.s[k];
				if (q < 36) q = 36;
				if (q > 127) q = 127;
				s += param - q_int2real[q];
				if (s > max) max = s, beg = tmp, end = k + 1;
				if (s < 0) s = 0, tmp = k + 1;
			}
			if (end - beg < min_len) {
				int64_t is = 0, imax;
				for (k = 0; k < min_len; ++k) is += (signed char)r->qual.s[k];
				for (imax = is, beg = 0; k < l; ++k) {
					is += (int)(signed char)r->qual.s[k] - (signed char)r->qual.s[k - min_len];
					if (imax < is) imax = is, beg = k - min_len + 1;
				}
				end = beg + min_len;
			}
		} else {
			beg = 0; end = l;
		}
		if (beg > 0 || end < l) {
			memmove(r->seq.s, r->seq.s + beg, (size_t)(end - beg));
			r->seq.l = (size_t)(end - beg);
			r->seq.s[r->seq.l] = 0;
			if (r->qual.l) {
				memmove(r->qual.s, r->qual.s + beg, (size_t)(end - beg));
				r->qual.l = (size_t)(end - beg);
				r->qual.s[r->qual.l] = 0;
			}
		}
		out_rec(stdout, r, UINT_MAX);
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}
