	}
	s0 = rec_init(ks0);
	s1 = rec_init(ks1);
	while (rec_read(s0) >= 0) {
		size_t min_l, l;
		rec_read(s1);
		if (strcmp(s0->name.s, s1->name.s ? s1->name.s : ""))
			fprintf(stderr, "[stk_famask] Different sequence names: %s != %s\n", s0->name.s, s1->name.s ? s1->name.s : "");
		if (s0->seq.l != s1->seq.l)
			fprintf(stderr, "[stk_famask] Unequal sequence length: %ld != %ld\n", (long)s0->seq.l, (long)s1->seq.l);
		min_l = s0->seq.l < s1->seq.l ? s0->seq.l : s1->seq.l;
		printf(">%s", s0->name.s);
