			putchar(out);
		}
		putchar('\n');
	}
	rec_destroy(s0); rec_destroy(s1);
	in_close(ks0); in_close(ks1);
	return 0;
}

/* ===================== dropse / rename ===================== */

typedef struct { str_t name, comment, seq, qual; } stash_t;

static void stash_copy(stash_t *d, const rec_t *r)
{
	str_copy_nonempty(&d->name, &r->name);
	str_copy_nonempty(&d->comment, &r->comment);
	str_copy_nonempty(&d->seq, &r->seq);
	str_copy_nonempty(&d->qual, &r->qual);
}

static int is_pair_name(const char *a, size_t la, const char *b, size_t lb)
{
	if (la != lb) return 0;
	if (strcmp(a, b) == 0) return 1;
	if (la >= 3 && a[la-2] == '/' && b[lb-2] == '/' && isdigit((unsigned char)a[la-1]) && isdigit((unsigned char)b[lb-1])
		&& strncmp(a, b, la - 2) == 0) return 1;
	return 0;
}

int cmd_dropse(int argc, char *argv[])
{
	instream_t *ks;
	rec_t *r;
	stash_t last;
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk dropse <in.fq>\n");
		return 1;
	}
	ks = in_open(argc > 1 ? argv[1] : "-");
	if (ks == 0) {
		OPEN_FAIL("stk_dropse");
		return 1;
	}
	memset(&last, 0, sizeof(last));
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		if (last.name.l && is_pair_name(last.name.s, last.name.l, r->name.s, r->name.l)) {
			out_record(stdout, last.name.s, 0, &last.comment, &last.seq, &last.qual, UINT_MAX);
			out_rec(stdout, r, UINT_MAX);
			last.name.l = 0;
		} else stash_copy(&last, r);
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

int cmd_rename(int argc, char *argv[])
{
	instream_t *ks;
	rec_t *r;
	stash_t last;
	const char *prefix;
	uint64_t n = 1;
	char *nbuf;
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk rename <in.fq> [prefix]\n");
		return 1;
	}
	ks = in_open(argc > 1 ? argv[1] : "-");
	if (ks == 0) {
		OPEN_FAIL("stk_rename");
		return 1;
	}
	prefix = argc > 2 ? argv[2] : "";
	nbuf = (char*)malloc(strlen(prefix) + 32);
	memset(&last, 0, sizeof(last));
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		if (last.name.l) {
			if (is_pair_name(last.name.s, last.name.l, r->name.s, r->name.l)) {
				sprintf(nbuf, "%s%lu", prefix, (unsigned long)n);
				out_record(stdout, nbuf, 0, &last.comment, &last.seq, &last.qual, UINT_MAX);
				out_record(stdout, nbuf, 0, &r->comment, &r->seq, &r->qual, UINT_MAX);
				++n;
				last.name.l = 0;
			} else {
				sprintf(nbuf, "%s%lu", prefix, (unsigned long)n);
				out_record(stdout, nbuf, 0, &last.comment, &last.seq, &last.qual, UINT_MAX);
				++n;
				stash_copy(&last, r);
			}
		} else stash_copy(&last, r);
	}
	if (last.name.l) {
		sprintf(nbuf, "%s%lu", prefix, (unsigned long)n);
		out_record(stdout, nbuf, 0, &last.comment, &last.seq, &last.qual, UINT_MAX);
	}
	free(nbuf);
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== randbase ===================== */

int cmd_randbase(int argc, char *argv[])
{
	instream_t *ks;
	rec_t *r;
	if (argc < 2) {
		fprintf(stderr, "Usage: seqtk randbase <in.fa>\n");
		return 1;
	}
	ks = in_open(argv[1]);
	if (ks == 0) {
		OPEN_FAIL("stk_randbase");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		size_t i;
		for (i = 0; i < r->seq.l; ++i) {
			unsigned char ch = (unsigned char)r->seq.s[i];
			int x = nt16_tab[ch];
			if (popcnt4(x) == 2) {
				int hi, lo, pick, k;
				for (hi = 3; hi >= 0; --hi) if (x >> hi & 1) break;
				for (lo = 0; lo < 4; ++lo) if (x >> lo & 1) break;
				pick = lcg48_drand() < 0.5 ? hi : lo;
				k = "ACGT"[pick];
				r->seq.s[i] = (char)(islower(ch) ? tolower(k) : k);
			}
		}
		putchar('>');
		fputs(r->name.s, stdout);
		out_wrapped60(stdout, r->seq.s, r->seq.l);
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== cutN ===================== */

static int find_next_cut(const rec_t *r, int64_t k, int min_n, int pen, int64_t *begin, int64_t *end)
{
	int64_t i, b, e, l = (int64_t)r->seq.l;
	const char *s = r->seq.s;
	while (k < l) {
		if (nt16_tab[(unsigned char)s[k]] == 15) {
			int64_t score, max;
			score = 0; e = max = -1;
			for (i = k; i < l && score >= 0; ++i) {
				if (nt16_tab[(unsigned char)s[i]] == 15) ++score;
				else score -= pen;
				if (score > max) max = score, e = i;
			}
			score = 0; b = max = -1;
			for (i = e; i >= 0 && score >= 0; --i) {
				if (nt16_tab[(unsigned char)s[i]] == 15) ++score;
				else score -= pen;
				if (score > max) max = score, b = i;
			}
			if (e + 1 - b >= min_n) {
				*begin = b;
				*end = e + 1;
				return 1;
			}
			k = e + 1;
		} else ++k;
	}
	return 0;
}

static void cutN_print(const rec_t *r, int64_t begin, int64_t end)
{
	int64_t i;
	if (begin >= end) return;
	printf(">%s:%ld-%ld", r->name.s, (long)(begin + 1), (long)end);
	for (i = begin; i < end && i < (int64_t)r->seq.l; ++i) {
		if ((i - begin) % 60 == 0) putchar('\n');
		putchar(r->seq.s[i]);
	}
	putchar('\n');
}

int cmd_cutN(int argc, char *argv[])
{
	int c, min_n = 1000, pen = 10, gap_only = 0;
	instream_t *ks;
	rec_t *r;
	while ((c = getopt(argc, argv, "n:p:g")) >= 0) {
		switch (c) {
		case 'n': min_n = atoi(optarg); break;
		case 'p': pen = atoi(optarg); break;
		case 'g': gap_only = 1; break;
		default: return 1;
		}
	}
	if (argc == optind) {
		fprintf(stderr, "\n");
		fprintf(stderr, "Usage:   seqtk cutN [options] <in.fa>\n\n");
		fprintf(stderr, "Options: -n INT    min size of N tract [%d]\n", min_n);
		fprintf(stderr, "         -p INT    penalty for a non-N [%d]\n", pen);
		fprintf(stderr, "         -g        print gaps only, no sequence\n\n");
		return 1;
	}
	ks = in_open(argv[optind]);
	if (ks == 0) {
		OPEN_FAIL("stk_cutN");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		int64_t k = 0, b, e;
		while (find_next_cut(r, k, min_n, pen, &b, &e)) {
			if (k < b) {
				if (!gap_only) cutN_print(r, k, b);
				else printf("%s\t%ld\t%ld\n", r->name.s, (long)b, (long)e);
			}
			k = e;
		}
		if (!gap_only) cutN_print(r, k, (int64_t)r->seq.l);
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== gap ===================== */

int cmd_gap(int argc, char *argv[])
{
	int c, min_l = 50;
	instream_t *ks;
