/* ===================== telo ===================== */

static void telo_usage(const char *motif, int pen, int max_drop, int min_score)
{
	fprintf(stderr, "Usage: seqtk telo [options] <in.fq>\n");
	fprintf(stderr, "Options:\n");
	fprintf(stderr, "  -m STR     motif [%s]\n", motif);
	fprintf(stderr, "  -p INT     penalty [%d]\n", pen);
	fprintf(stderr, "  -d INT     max drop [%d]\n", max_drop);
	fprintf(stderr, "  -s INT     min score [%d]\n", min_score);
	fprintf(stderr, "  -P         print scoring\n");
}

static int in_set(const uint64_t *a, int n, uint64_t x)
{
	int i;
	for (i = 0; i < n; ++i) if (a[i] == x) return 1;
	return 0;
}

int cmd_telo(int argc, char *argv[])
{
	int c, pen = 1, max_drop = 2000, min_score = 300, print_score = 0, k, i;
	char *motif = "CCCTAA";
	uint64_t mask, rot[64], code[64];
	instream_t *ks;
	rec_t *r;
	uint64_t sum_telo = 0, sum_len = 0;
	const char *fn;
	while ((c = getopt(argc, argv, "m:p:d:s:P")) >= 0) {
		switch (c) {
		case 'm': motif = optarg; break;
		case 'p': pen = atoi(optarg); break;
		case 'd': max_drop = atoi(optarg); break;
		case 's': min_score = atoi(optarg); break;
		case 'P': print_score = 1; break;
		default: break;
		}
	}
	if (argc == optind && isatty(fileno(stdin))) {
		telo_usage(motif, pen, max_drop, min_score);
		return 1;
	}
	if (argc == 1) fn = "-";
	else {
		if (optind >= argc) crash_segv();
		fn = argv[optind];
	}
	k = (int)strlen(motif);
	if (k > 32) k = 32;
	for (i = 0; i < k; ++i) {
		int x = nt6_code((unsigned char)motif[i]);
		if (!(x >= 1 && x <= 4)) fail_assert("c >= 1 && c <= 4", 2005, "stk_telo");
		code[i] = (uint64_t)(x - 1);
	}
	mask = k >= 32 ? ~0ULL : (1ULL << (2 * k)) - 1;
	for (i = 0; i < k; ++i) {
		int j;
		uint64_t x = 0;
		for (j = 0; j < k; ++j) x = x << 2 | code[(i + j) % k];
		rot[i] = x;
	}
	ks = in_open(fn);
	if (ks == 0) {
		OPEN_FAIL("stk_telo");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		int64_t len = (int64_t)r->seq.l, j, end5 = 0, st3 = len;
		int64_t score, max, max_i, l;
		uint64_t x;
		sum_len += (uint64_t)len;
		/* 5' end */
		score = max = 0; max_i = -1; l = 0; x = 0;
		for (j = 0; j < len; ++j) {
			int b;
			if (print_score) printf("P\t%s\t%ld\t%ld\t%ld\n", r->name.s, (long)j, (long)score, (long)max);
			b = nt4_tab[(unsigned char)r->seq.s[j]];
			if (b < 4) { x = (x << 2 | (uint64_t)b) & mask; ++l; }
			else l = 0, x = 0;
			if (j >= k) {
				if (l >= k && in_set(rot, k, x)) ++score;
				else score -= pen;
			}
			if (score > max) max = score, max_i = j;
			else if (max - score > max_drop) break;
		}
		if (max >= min_score && max_i >= 0) end5 = max_i + 1;
		/* 3' end */
		score = max = 0; max_i = -1; l = 0; x = 0;
		for (j = 1; j <= len - end5; ++j) {
			int64_t p = len - j;
			int b;
			if (print_score) printf("Q\t%s\t%ld\t%ld\t%ld\n", r->name.s, (long)j, (long)score, (long)max);
			b = nt4_tab[(unsigned char)r->seq.s[p]];
			if (b < 4) {
				x = (x << 2 | (uint64_t)(3 - b)) & mask;
				++l;
			} else l = 0, x = 0;
			if (j >= k) {
				if (l >= k && in_set(rot, k, x)) ++score;
				else score -= pen;
			}
			if (score > max) max = score, max_i = p;
			else if (max - score > max_drop) break;
		}
		if (max >= min_score && max_i >= 0) st3 = max_i;
		if (end5 > 0) {
			if (!print_score) printf("%s\t0\t%ld\t%ld\n", r->name.s, (long)end5, (long)len);
			sum_telo += (uint64_t)end5;
		}
		if (st3 < len) {
			if (!print_score) printf("%s\t%ld\t%ld\t%ld\n", r->name.s, (long)st3, (long)len, (long)len);
			sum_telo += (uint64_t)(len - st3);
		}
	}
	fprintf(stderr, "%lu\t%lu\n", (unsigned long)sum_telo, (unsigned long)sum_len);
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== kfreq ===================== */

static inline int kmer_dist(uint64_t a, uint64_t b, uint64_t m1)
{
	uint64_t d = a ^ b;
	d = (d | d >> 1) & m1;
	return __builtin_popcountll(d);
}

int cmd_kfreq(int argc, char *argv[])
{
	int k, i;
	uint64_t fwd = 0, rev = 0, mask, m1 = 0;
	instream_t *ks;
	rec_t *r;
	if (argc < 2) {
		fprintf(stderr, "Usage: seqtk kfreq <kmer> <in.fa>\n");
		return 1;
	}
	k = (int)strlen(argv[1]);
	if (k > 32) k = 32;
	for (i = 0; i < k; ++i) {
		int x = nt6_code((unsigned char)argv[1][i]);
		if (!(x >= 1 && x <= 4)) fail_assert("c >= 1 && c <= 4", 1794, "stk_kfreq");
		fwd = fwd << 2 | (uint64_t)(x - 1);
		rev |= (uint64_t)(4 - x) << (2 * i);
	}
	mask = k >= 32 ? ~0ULL : (1ULL << (2 * k)) - 1;
	for (i = 0; i < k; ++i) m1 |= 1ULL << (2 * i);
	ks = in_open(argc > 2 ? argv[2] : "-");
	if (ks == 0) {
		OPEN_FAIL("stk_kfreq");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		size_t j;
		int l = 0;
		uint64_t x = 0;
		long fn = 0, rn = 0, fe = 0, re = 0;
		for (j = 0; j < r->seq.l; ++j) {
			int b = nt4_tab[(unsigned char)r->seq.s[j]];
			if (b < 4) {
				x = (x << 2 | (uint64_t)b) & mask;
				if (++l >= k) {
					if (kmer_dist(x, fwd, m1) <= 1) ++fn;
					else if (kmer_dist(x, rev, m1) <= 1) ++rn;
					if (x == fwd) ++fe;
					else if (x == rev) ++re;
				}
			} else l = 0, x = 0;
		}
		if (fn > rn) printf("%s\t%ld\t+\t%ld\t%ld\n", r->name.s, (long)r->seq.l, fn, fe);
		else printf("%s\t%ld\t-\t%ld\t%ld\n", r->name.s, (long)r->seq.l, rn, re);
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}
