#include "core.h"
#include "cmds.h"

#define OPEN_FAIL(func) fprintf(stderr, "[E::%s] failed to open the input file/stream.\n", func)

/* ===================== hety ===================== */

int cmd_hety(int argc, char *argv[])
{
	int c, win = 50000, n_start = 5, lower_mask = 0, step;
	instream_t *ks;
	rec_t *r;
	uint64_t *cum_good = 0, *cum_het = 0;
	size_t cap = 0;
	while ((c = getopt(argc, argv, "w:t:m")) >= 0) {
		switch (c) {
		case 'w': win = atoi(optarg); break;
		case 't': n_start = atoi(optarg); break;
		case 'm': lower_mask = 1; break;
		default: break;
		}
	}
	if (argc == 1) {
		fprintf(stderr, "\n");
		fprintf(stderr, "Usage:   seqtk hety [options] <in.fa>\n\n");
		fprintf(stderr, "Options: -w INT   window size [%d]\n", win);
		fprintf(stderr, "         -t INT   # start positions in a window [%d]\n", n_start);
		fprintf(stderr, "         -m       treat lowercases as masked\n");
		fprintf(stderr, "\n");
		return 1;
	}
	if (n_start == 0) crash_fpe();
	step = win / n_start;
	if (optind >= argc) crash_segv();
	ks = in_open(argv[optind]);
	if (ks == 0) {
		OPEN_FAIL("stk_hety");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		size_t i, l = r->seq.l;
		int64_t prev = 0, j;
		if (l + 1 > cap) {
			cap = l + 1;
			cum_good = (uint64_t*)realloc(cum_good, cap * sizeof(uint64_t));
			cum_het = (uint64_t*)realloc(cum_het, cap * sizeof(uint64_t));
		}
		cum_good[0] = cum_het[0] = 0;
		for (i = 0; i < l; ++i) {
			unsigned char ch = (unsigned char)r->seq.s[i];
			int x = nt16_tab[ch], b = popcnt4(x), g = 0, h = 0;
			if (!(lower_mask && islower(ch))) {
				if (b == 1) g = 1;
				else if (b == 2) g = 1, h = 1;
			}
			cum_good[i + 1] = cum_good[i] + g;
			cum_het[i + 1] = cum_het[i] + h;
		}
		for (j = 1; j <= (int64_t)l; ++j) {
			int64_t st, en;
			if (j == (int64_t)l) {
				st = prev; en = j;
			} else if (j >= win) {
				if (step == 0) crash_fpe();
				if (j % step != 0) continue;
				st = j - win; en = j;
			} else continue;
			{
				uint64_t g = cum_good[en] - cum_good[st], h = cum_het[en] - cum_het[st];
				if (g > 0)
					printf("%s\t%ld\t%ld\t%.2lf\t%lu\t%lu\n", r->name.s, (long)prev, (long)j,
						(double)h / (double)g * win, (unsigned long)g, (unsigned long)h);
			}
			prev = j;
		}
	}
	free(cum_good); free(cum_het);
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== gc ===================== */

int cmd_gc(int argc, char *argv[])
{
	int c, is_at = 0, min_l = 20;
	double frac = 0.6f, xdrop = 10.0, h;
	instream_t *ks;
	rec_t *r;
	while ((c = getopt(argc, argv, "wx:f:l:")) >= 0) {
		switch (c) {
		case 'w': is_at = 1; break;
		case 'x': xdrop = atof(optarg); break;
		case 'f': frac = atof(optarg); break;
		case 'l': min_l = atoi(optarg); break;
		default: break;
		}
	}
	if (optind + 1 > argc) {
		fprintf(stderr, "Usage: seqtk gc [options] <in.fa>\n");
		fprintf(stderr, "Options:\n");
		fprintf(stderr, "  -w         identify high-AT regions\n");
		fprintf(stderr, "  -f FLOAT   min GC fraction (or AT fraction for -w) [%.2f]\n", frac);
		fprintf(stderr, "  -l INT     min region length to output [%d]\n", min_l);
		fprintf(stderr, "  -x FLOAT   X-dropoff [%.1f]\n", xdrop);
		return 1;
	}
	ks = in_open(argv[optind]);
	if (ks == 0) {
		OPEN_FAIL("stk_gc");
		return 1;
	}
	h = (1.0 - frac) / frac;
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		int64_t l = (int64_t)r->seq.l, i = 0, start = 0, max_i = -1, k;
		double sc = 0., max = 0.;
		const char *s = r->seq.s;
		uint64_t guard = 0;
		while (i < l) {
			int x = nt16_tab[(unsigned char)s[i]];
			int hit = is_at ? (x == 1 || x == 8 || x == 9) : (x == 2 || x == 4 || x == 6);
			if (sc <= 0. && !hit) { ++i; continue; }
			if (sc <= 0.) start = i;
			sc += hit ? h : -1.0;
			if (sc > max) max = sc, max_i = i;
			else if (sc < 0. || max - sc > xdrop) {
				if (max_i + 1 - start >= min_l) {
					int64_t nh = 0;
					for (k = start; k <= max_i; ++k) {
						int y = nt16_tab[(unsigned char)s[k]];
						nh += is_at ? (y == 1 || y == 8 || y == 9) : (y == 2 || y == 4 || y == 6);
					}
					printf("%s\t%ld\t%ld\t%ld\n", r->name.s, (long)start, (long)(max_i + 1), (long)nh);
				}
				sc = max = 0.;
				i = max_i + 1;
				if (++guard > (uint64_t)l * 4 + 16) break;
				continue;
			}
			++i;
		}
		if (max > 0. && max_i + 1 - start >= min_l) {
			int64_t nh = 0;
			for (k = start; k <= max_i; ++k) {
				int y = nt16_tab[(unsigned char)s[k]];
				nh += is_at ? (y == 1 || y == 8 || y == 9) : (y == 2 || y == 4 || y == 6);
			}
			printf("%s\t%ld\t%ld\t%ld\n", r->name.s, (long)start, (long)(max_i + 1), (long)nh);
		}
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== mutfa ===================== */

typedef struct { int64_t pos; int base; } snp_t;

int cmd_mutfa(int argc, char *argv[])
{
	instream_t *ks, *ksnp;
	rec_t *r;
	str_t name = {0,0,0}, tok = {0,0,0};
	int dret;
	/* store per-name lists in a reghash (beg = pos, end = base) */
	reghash_t *h;
	if (argc < 3) {
		fprintf(stderr, "Usage: seqtk mutfa <in.fa> <in.snp>\n\n");
		fprintf(stderr, "Note: <in.snp> contains at least four columns per line which are:\n");
		fprintf(stderr, "      'chr  1-based-pos  any  base-changed-to'.\n");
		return 1;
	}
	ksnp = in_open(argv[2]);
	if (ksnp == 0) {
		OPEN_FAIL("stk_mutfa");
		return 1;
	}
	h = reg_new();
	while (in_getuntil(ksnp, SEP_SPACE, &name, &dret, 0) >= 0) {
		int64_t pos = 0;
		int ret;
		char *nm = strdup(name.s);
		if (in_getuntil(ksnp, SEP_SPACE, &tok, &dret, 0) > 0) pos = atol(tok.s) - 1;
		in_getuntil(ksnp, SEP_SPACE, &tok, &dret, 0);
		ret = in_getuntil(ksnp, SEP_SPACE, &tok, &dret, 0);
		if (ret == 1 && isalpha((unsigned char)tok.s[0])) {
			reg_entry_t *e = reg_add(h, nm);
			reg_push(e, pos, (unsigned char)tok.s[0], 0);
		}
		free(nm);
		if (dret != '\n') while ((dret = in_getc(ksnp)) > 0 && dret != '\n');
	}
	in_close(ksnp);
	free(name.s); free(tok.s);
	ks = in_open(argv[1]);
	if (ks == 0) {
		OPEN_FAIL("stk_mutfa");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		reg_entry_t *e = reg_get(h, r->name.s);
		if (e) {
			size_t j;
			for (j = 0; j < e->n; ++j)
				if (e->a[j].beg >= 0 && e->a[j].beg < (int64_t)r->seq.l)
					r->seq.s[e->a[j].beg] = (char)e->a[j].end;
		}
		putchar('>');
		fputs(r->name.s, stdout);
		out_wrapped60(stdout, r->seq.s, r->seq.l);
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== mergefa ===================== */

int cmd_mergefa(int argc, char *argv[])
{
	int c, is_intersect = 0, is_haploid = 0, qual = 0, is_mask = 0, is_randhet = 0;
	instream_t *ks0, *ks1;
	rec_t *s0, *s1;
	uint64_t cnt[5] = {0,0,0,0,0};
	while ((c = getopt(argc, argv, "himq:r")) >= 0) {
		switch (c) {
		case 'i': is_intersect = 1; break;
		case 'h': is_haploid = 1; break;
		case 'm': is_mask = 1; break;
		case 'r': is_randhet = 1; break;
		case 'q': qual = atoi(optarg); break;
		default:
			fprintf(stderr, "\nUsage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\n");
			fprintf(stderr, "Options: -q INT   quality threshold [0]\n");
			fprintf(stderr, "         -i       take intersection\n");
			fprintf(stderr, "         -m       convert to lowercase when one of the input base is N\n");
			fprintf(stderr, "         -r       pick a random allele from het\n");
			fprintf(stderr, "         -h       suppress hets in the input\n\n");
			return 1;
		}
	}
	if (is_mask && is_intersect) {
		fprintf(stderr, "[stk_mergefa] `-i' and `-h' cannot be applied at the same time.\n");
		return 1;
	}
	if (optind + 2 > argc) {
		fprintf(stderr, "\nUsage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\n");
		fprintf(stderr, "Options: -q INT   quality threshold [0]\n");
		fprintf(stderr, "         -i       take intersection\n");
		fprintf(stderr, "         -m       convert to lowercase when one of the input base is N\n");
		fprintf(stderr, "         -r       pick a random allele from het\n");
		fprintf(stderr, "         -h       suppress hets in the input\n\n");
		return 1;
	}
	ks0 = in_open(argv[optind]);
	ks1 = in_open(argv[optind + 1]);
	if (ks0 == 0 || ks1 == 0) {
		OPEN_FAIL("stk_mergefa");
		return 1;
	}
	s0 = rec_init(ks0);
	s1 = rec_init(ks1);
	lcg48_seed(11);
	while (rec_read(s0) >= 0) {
		size_t min_l, l;
		rec_read(s1);
		if (strcmp(s0->name.s, s1->name.s ? s1->name.s : ""))
			fprintf(stderr, "[stk_mergefa] Different sequence names: %s != %s\n", s0->name.s, s1->name.s ? s1->name.s : "");
		if (s0->seq.l != s1->seq.l)
			fprintf(stderr, "[stk_mergefa] Unequal sequence length: %ld != %ld\n", (long)s0->seq.l, (long)s1->seq.l);
		min_l = s0->seq.l < s1->seq.l ? s0->seq.l : s1->seq.l;
		printf(">%s", s0->name.s);
		for (l = 0; l < min_l; ++l) {
			int c0 = (unsigned char)s0->seq.s[l], c1 = (unsigned char)s1->seq.s[l];
			int n0, n1, b0, b1, is_upper, out;
			if (s0->qual.l && s0->qual.s[l] - 33 < qual) c0 = tolower(c0);
			if (s1->qual.l && s1->qual.s[l] - 33 < qual) c1 = tolower(c1);
			if (is_intersect || is_mask) is_upper = (isupper(c0) || isupper(c1)) ? 1 : 0;
			else is_upper = (isupper(c0) && isupper(c1)) ? 1 : 0;
			n0 = nt16_tab[c0]; n1 = nt16_tab[c1];
			if (n0 == 0) n0 = 15;
			if (n1 == 0) n1 = 15;
			b0 = popcnt4(n0); b1 = popcnt4(n1);
			if (is_upper) {
				if (b0 == 1 && b1 == 1) {
					if (n0 == n1) ++cnt[0];
					else ++cnt[1];
				} else if (b0 == 1 && b1 == 2) ++cnt[2];
				else if (b0 == 2 && b1 == 1) ++cnt[3];
				else if (b0 == 2 && b1 == 2) ++cnt[4];
			}
			if (is_haploid && (b0 > 1 || b1 > 1)) is_upper = 0;
			if (is_intersect) {
				n0 &= n1;
				if (n0 == 0) is_upper = 0;
			} else if (is_mask) {
				if (n0 == 15 || n1 == 15) is_upper = 0;
				n0 &= n1;
				if (n0 == 0) is_upper = 0;
			} else if (is_randhet) {
				if (b0 == 1 && b1 == 1) {
					n0 |= n1;
				} else if (((b0 == 1 && b1 == 2) || (b0 == 2 && b1 == 1)) && (n0 & n1)) {
					n0 = (lcg48_lrand() & 1) ? (n0 & n1) : (n0 | n1);
				} else if (b0 == 2 && b1 == 2 && n0 == n1) {
					if (lcg48_lrand() & 1) {
						int i;
						if (lcg48_lrand() & 1) {
							for (i = 8; i >= 1; i >>= 1)
								if (n0 & i) n0 &= i;
						} else {
							for (i = 1; i <= 8; i <<= 1)
								if (n0 & i) n0 &= i;
						}
					}
				} else is_upper = 0;
			} else n0 |= n1;
			out = nt16_rev[n0];
			if (!is_upper) out = tolower(out);
			if (l % 60 == 0) putchar('\n');
			putchar(out);
		}
		putchar('\n');
	}
	fprintf(stderr, "[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=(%ld,%ld,%ld,%ld,%ld)\n",
		(long)cnt[0], (long)cnt[1], (long)cnt[2], (long)cnt[3], (long)cnt[4]);
	rec_destroy(s0); rec_destroy(s1);
	in_close(ks0); in_close(ks1);
	return 0;
}

