/* ===================== dropse / rename ===================== */

typedef struct { str_t name, comment, seq, qual; } stash_t;

static void stash_copy(stash_t *d, const rec_t *r)
{
	str_copy_nonempty(&d->name, &r->name);
	str_copy_nonempty(&d->comment, &r->comment);
	str_copy_nonempty(&d->seq, &r->seq);
	str_copy_nonempty(&d->qual, &r->qual);
}

static int is_pair_name(const char *a, size_t la, const char *b, size_t lb)
{
	if (la != lb) return 0;
	if (strcmp(a, b) == 0) return 1;
	if (la >= 3 && a[la-2] == '/' && b[lb-2] == '/' && isdigit((unsigned char)a[la-1]) && isdigit((unsigned char)b[lb-1])
		&& strncmp(a, b, la - 2) == 0) return 1;
	return 0;
}

int cmd_dropse(int argc, char *argv[])
{
	instream_t *ks;
	rec_t *r;
	stash_t last;
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk dropse <in.fq>\n");
		return 1;
	}
	ks = in_open(argc > 1 ? argv[1] : "-");
	if (ks == 0) {
		OPEN_FAIL("stk_dropse");
		return 1;
	}
	memset(&last, 0, sizeof(last));
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		if (last.name.l && is_pair_name(last.name.s, last.name.l, r->name.s, r->name.l)) {
			out_record(stdout, last.name.s, 0, &last.comment, &last.seq, &last.qual, UINT_MAX);
			out_rec(stdout, r, UINT_MAX);
			last.name.l = 0;
		} else stash_copy(&last, r);
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

int cmd_rename(int argc, char *argv[])
{
	instream_t *ks;
	rec_t *r;
	stash_t last;
	const char *prefix;
	uint64_t n = 1;
	char *nbuf;
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk rename <in.fq> [prefix]\n");
		return 1;
	}
	ks = in_open(argc > 1 ? argv[1] : "-");
	if (ks == 0) {
		OPEN_FAIL("stk_rename");
		return 1;
	}
	prefix = argc > 2 ? argv[2] : "";
	nbuf = (char*)malloc(strlen(prefix) + 32);
	memset(&last, 0, sizeof(last));
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		if (last.name.l) {
			if (is_pair_name(last.name.s, last.name.l, r->name.s, r->name.l)) {
				sprintf(nbuf, "%s%lu", prefix, (unsigned long)n);
				out_record(stdout, nbuf, 0, &last.comment, &last.seq, &last.qual, UINT_MAX);
				out_record(stdout, nbuf, 0, &r->comment, &r->seq, &r->qual, UINT_MAX);
				++n;
				last.name.l = 0;
			} else {
				sprintf(nbuf, "%s%lu", prefix, (unsigned long)n);
				out_record(stdout, nbuf, 0, &last.comment, &last.seq, &last.qual, UINT_MAX);
				++n;
				stash_copy(&last, r);
			}
		} else stash_copy(&last, r);
	}
	if (last.name.l) {
		sprintf(nbuf, "%s%lu", prefix, (unsigned long)n);
		out_record(stdout, nbuf, 0, &last.comment, &last.seq, &last.qual, UINT_MAX);
	}
	free(nbuf);
	rec_destroy(r);
	in_close(ks);
	return 0;
}

