		OPEN_FAIL("stk_randbase");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		size_t i;
		for (i = 0; i < r->seq.l; ++i) {
			unsigned char ch = (unsigned char)r->seq.s[i];
			int x = nt16_tab[ch];
			if (popcnt4(x) == 2) {
				int hi, lo, pick, k;
				for (hi = 3; hi >= 0; --hi) if (x >> hi & 1) break;
				for (lo = 0; lo < 4; ++lo) if (x >> lo & 1) break;
				pick = lcg48_drand() < 0.5 ? hi : lo;
				k = "ACGT"[pick];
				r->seq.s[i] = (char)(islower(ch) ? tolower(k) : k);
			}
		}
		putchar('>');
		fputs(r->name.s, stdout);
		out_wrapped60(stdout, r->seq.s, r->seq.l);
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== cutN ===================== */

static int find_next_cut(const rec_t *r, int64_t k, int min_n, int pen, int64_t *begin, int64_t *end)
{
	int64_t i, b, e, l = (int64_t)r->seq.l;
	const char *s = r->seq.s;
	while (k < l) {
		if (nt16_tab[(unsigned char)s[k]] == 15) {
			int64_t score, max;
			score = 0; e = max = -1;
			for (i = k; i < l && score >= 0; ++i) {
				if (nt16_tab[(unsigned char)s[i]] == 15) ++score;
				else score -= pen;
				if (score > max) max = score, e = i;
			}
			score = 0; b = max = -1;
			for (i = e; i >= 0 && score >= 0; --i) {
				if (nt16_tab[(unsigned char)s[i]] == 15) ++score;
				else score -= pen;
				if (score > max) max = score, b = i;
			}
			if (e + 1 - b >= min_n) {
				*begin = b;
				*end = e + 1;
				return 1;
			}
			k = e + 1;
		} else ++k;
	}
	return 0;
}

static void cutN_print(const rec_t *r, int64_t begin, int64_t end)
{
	int64_t i;
	if (begin >= end) return;
	printf(">%s:%ld-%ld", r->name.s, (long)(begin + 1), (long)end);
	for (i = begin; i < end && i < (int64_t)r->seq.l; ++i) {
		if ((i - begin) % 60 == 0) putchar('\n');
		putchar(r->seq.s[i]);
	}
	putchar('\n');
}

int cmd_cutN(int argc, char *argv[])
{
	int c, min_n = 1000, pen = 10, gap_only = 0;
	instream_t *ks;
	rec_t *r;
	while ((c = getopt(argc, argv, "n:p:g")) >= 0) {
		switch (c) {
		case 'n': min_n = atoi(optarg); break;
		case 'p': pen = atoi(optarg); break;
		case 'g': gap_only = 1; break;
		default: return 1;
		}
	}
	if (argc == optind) {
		fprintf(stderr, "\n");
		fprintf(stderr, "Usage:   seqtk cutN [options] <in.fa>\n\n");
		fprintf(stderr, "Options: -n INT    min size of N tract [%d]\n", min_n);
		fprintf(stderr, "         -p INT    penalty for a non-N [%d]\n", pen);
		fprintf(stderr, "         -g        print gaps only, no sequence\n\n");
		return 1;
	}
	ks = in_open(argv[optind]);
	if (ks == 0) {
		OPEN_FAIL("stk_cutN");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		int64_t k = 0, b, e;
		while (find_next_cut(r, k, min_n, pen, &b, &e)) {
			if (k < b) {
				if (!gap_only) cutN_print(r, k, b);
				else printf("%s\t%ld\t%ld\n", r->name.s, (long)b, (long)e);
			}
			k = e;
		}
		if (!gap_only) cutN_print(r, k, (int64_t)r->seq.l);
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

/* ===================== gap ===================== */

int cmd_gap(int argc, char *argv[])
{
	int c, min_l = 50;
	instream_t *ks;
	rec_t *r;
	while ((c = getopt(argc, argv, "l:")) >= 0) {
		if (c == 'l') min_l = atoi(optarg);
	}
	if (argc == 1) {
		fprintf(stderr, "Usage: seqtk gap [-l %d] <in.fa>\n", min_l);
		return 1;
	}
	if (optind >= argc) crash_segv();
	ks = in_open(argv[optind]);
	if (ks == 0) {
		OPEN_FAIL("stk_gap");
		return 1;
	}
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		int64_t i, l = (int64_t)r->seq.l, st = -1;
		for (i = 0; i <= l; ++i) {
			int is_gap = i < l && nt4_tab[(unsigned char)r->seq.s[i]] > 3;
			if (is_gap) {
				if (st < 0) st = i;
			} else if (st >= 0) {
				if (i - st >= min_l) printf("%s\t%ld\t%ld\n", r->name.s, (long)st, (long)i);
				st = -1;
			}
		}
	}
	rec_destroy(r);
	in_close(ks);
	return 0;
}

