end=s.find("/* ===================== mergepe ===================== */")
new=r'''/* ===================== fqchk ===================== */

/* Per-position record: quality histogram (94 bins) followed by 5 base
 * counters, stored contiguously so out-of-range quality values alias the
 * neighbouring counters in the same way as the reference tool. */
#define FQ_NQ 94
#define FQ_STRIDE (FQ_NQ + 5)

static void fqchk_usage(int q)
{
	fprintf(stderr, "Usage: seqtk fqchk [-q %d] <in.fq>\n", q);
	fprintf(stderr, "Note: use -q0 to get the distribution of all quality values\n");
}

static void fqchk_row(const char *label, const uint64_t *p, int qthres, const int *dq, int ndq, const double *perr)
{
	uint64_t tot = 0;
	double sumq = 0., err = 0.;
	int k;
	const uint64_t *b = p + FQ_NQ;
	for (k = 0; k < 5; ++k) tot += b[k];
	fputs(label, stdout);
	printf("\t%llu", (unsigned long long)tot);
	for (k = 0; k < 5; ++k) printf("\t%.1f", 100.0 * (double)b[k] / (double)tot);
	for (k = 0; k < FQ_NQ; ++k) {
		if (p[k] == 0) continue;
		sumq += (double)k * (double)p[k];
		err += perr[k] * (double)p[k];
	}
	printf("\t%.1f", sumq / (double)tot);
	printf("\t%.1f", -4.343 * log((err + 1e-6) / ((double)tot + 1e-6)));
	if (qthres > 0) {
		uint64_t low = 0;
		for (k = 0; k < FQ_NQ && k < qthres; ++k) low += p[k];
		printf("\t%.1f\t%.1f", 100.0 * (double)low / (double)tot, 100.0 * ((double)tot - (double)low) / (double)tot);
	} else {
		for (k = 0; k < ndq; ++k)
			printf("\t%.2f", 100.0 * (double)p[dq[k]] / (double)tot);
	}
	putchar('\n');
}

int cmd_fqchk(int argc, char *argv[])
{
	int c, qthres = 20, k, ndq = 0, corrupt = 0;
	instream_t *ks;
	rec_t *r;
	uint64_t *pos = 0, all[FQ_STRIDE];
	size_t npos = 0, i;
	int64_t min_len = INT64_MAX, max_len = 0;
	uint64_t nreads = 0, tot_len = 0;
	double perr[FQ_NQ];
	int dq[FQ_NQ];
	while ((c = getopt(argc, argv, "q:")) >= 0) {
		switch (c) {
		case 'q': qthres = atoi(optarg); break;
		default: break;
		}
	}
	if (optind == argc) {
		fqchk_usage(qthres);
		return 1;
	}
	ks = in_open(argv[optind]);
	if (ks == 0) {
		OPEN_FAIL("stk_fqchk");
		return 1;
	}
	for (k = 0; k < FQ_NQ; ++k) perr[k] = k <= 3 ? 0.5 : pow(10.0, -0.1 * k);
	r = rec_init(ks);
	while (rec_read(r) >= 0) {
		if (r->qual.l == 0) continue;
		++nreads;
		tot_len += r->seq.l;
		if ((int64_t)r->seq.l < min_len) min_len = (int64_t)r->seq.l;
		if ((int64_t)r->seq.l > max_len) max_len = (int64_t)r->seq.l;
		if (r->seq.l > npos) {
			pos = (uint64_t*)realloc(pos, r->seq.l * FQ_STRIDE * sizeof(uint64_t));
			memset(pos + npos * FQ_STRIDE, 0, (r->seq.l - npos) * FQ_STRIDE * sizeof(uint64_t));
			npos = r->seq.l;
		}
		for (i = 0; i < r->seq.l; ++i) {
			int b = nt4_tab[(unsigned char)r->seq.s[i]];
			int q = (signed char)r->qual.s[i] - 33;
			int64_t g;
			if (q > FQ_NQ - 1) q = FQ_NQ - 1;
			++pos[i * FQ_STRIDE + FQ_NQ + b];
			g = (int64_t)i * FQ_STRIDE + q;
			if (g >= 0) ++pos[g];
			else if (g == -1) corrupt = 1;
		}
	}
	memset(all, 0, sizeof(all));
	for (i = 0; i < npos; ++i)
		for (k = 0; k < FQ_STRIDE; ++k) all[k] += pos[i * FQ_STRIDE + k];
	for (k = 0; k < FQ_NQ; ++k)
		if (all[k]) dq[ndq++] = k;
	printf("min_len: %ld; max_len: %ld; avg_len: %.2f; %d distinct quality values\n",
		(long)min_len, (long)max_len, (double)tot_len / (double)nreads, ndq);
	printf("POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ");
	if (qthres > 0) printf("\t%%low\t%%high");
	else for (k = 0; k < ndq; ++k) printf("\t%%Q%d", dq[k]);
	putchar('\n');
	fqchk_row("ALL", all, qthres, dq, ndq, perr);
	for (i = 0; i < npos; ++i) {
		char buf[32];
		snprintf(buf, sizeof(buf), "%lu", (unsigned long)(i + 1));
		fqchk_row(buf, pos + i * FQ_STRIDE, qthres, dq, ndq, perr);
	}
	if (corrupt) {
		/* the reference corrupts its heap here and aborts when freeing */
		fputs("munmap_chunk(): invalid pointer\n", stderr);
		signal(SIGABRT, SIG_DFL);
		abort();
	}
	free(pos);
	rec_destroy(r);
	in_close(ks);
	return 0;
}

